'use client';

import { useEffect, useState } from 'react';
import { getUserAnalytics, getRevenueAnalytics, getPlaybackAnalytics } from '@/lib/api';
import {
  AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip as RechartsTooltip, ResponsiveContainer, Legend,
} from 'recharts';
import { motion } from 'framer-motion';
import { TrendingUp, Users, CreditCard, Tv, Calendar } from 'lucide-react';

const DAYS_OPTIONS = [7, 14, 30, 60, 90];

function SectionCard({ title, children, icon: Icon, color }: {
  title: string; children: React.ReactNode; icon: React.ElementType; color: string;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="rounded-2xl border border-slate-700/50 bg-slate-900/40 backdrop-blur-xl overflow-hidden"
    >
      <div className="flex items-center gap-3 p-5 border-b border-slate-700/50">
        <div className={`p-2 rounded-xl bg-slate-800 ${color}`}>
          <Icon className="w-4 h-4" />
        </div>
        <h3 className="text-base font-bold text-slate-200">{title}</h3>
      </div>
      <div className="p-5">{children}</div>
    </motion.div>
  );
}

export default function AnalyticsPage() {
  const [days, setDays] = useState(30);
  const [userData, setUserData] = useState<unknown>(null);
  const [revenueData, setRevenueData] = useState<unknown[]>([]);
  const [playbackData, setPlaybackData] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = (d: number) => {
    setLoading(true);
    Promise.all([getUserAnalytics(d), getRevenueAnalytics(d), getPlaybackAnalytics()])
      .then(([u, r, p]) => {
        setUserData(u);
        setRevenueData(r || []);
        setPlaybackData(p || []);
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => { void Promise.resolve().then(() => fetchData(days)); }, [days]);

  // Merge signups + active into one series keyed by date
  const userChartData = (() => {
    if (!userData) return [];
    const map: Record<string, { date: string; signups: number; active: number }> = {};
    (userData.signups || []).forEach((r: unknown) => {
      const d = r.date?.substring(0, 10);
      if (!map[d]) map[d] = { date: d, signups: 0, active: 0 };
      map[d].signups = Number(r.count);
    });
    (userData.active || []).forEach((r: unknown) => {
      const d = r.date?.substring(0, 10);
      if (!map[d]) map[d] = { date: d, signups: 0, active: 0 };
      map[d].active = Number(r.count);
    });
    return Object.values(map).sort((a, b) => a.date.localeCompare(b.date)).map(r => ({
      ...r,
      date: new Date(r.date).toLocaleDateString('en-IN', { month: 'short', day: 'numeric' }),
    }));
  })();

  const revenueChartData = revenueData.map((r: unknown) => ({
    date: new Date(r.date).toLocaleDateString('en-IN', { month: 'short', day: 'numeric' }),
    revenue: parseFloat(r.revenue) || 0,
    txns: parseInt(r.count) || 0,
  }));

  const totalRevenue = revenueData.reduce((s: number, r: unknown) => s + (parseFloat(r.revenue) || 0), 0);
  const totalSignups = (userData?.signups || []).reduce((s: number, r: unknown) => s + (parseInt(r.count) || 0), 0);
  const totalActiveUsers = (userData?.active || []).reduce((s: number, r: unknown) => s + (parseInt(r.count) || 0), 0);

  const tooltipStyle = { backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '0.5rem', color: '#f8fafc' };

  return (
    <div className="space-y-8 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-cyan-400">Analytics</h1>
          <p className="text-slate-400 mt-1">Track growth, revenue and playback trends.</p>
        </div>
        <div className="flex items-center gap-2 bg-slate-800/60 border border-slate-700/50 rounded-xl p-1">
          {DAYS_OPTIONS.map(d => (
            <button
              key={d}
              onClick={() => setDays(d)}
              className={`px-3 py-1.5 rounded-lg text-sm font-semibold transition-all ${days === d ? 'bg-gradient-to-r from-emerald-500 to-cyan-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-200'}`}
            >
              {d}d
            </button>
          ))}
        </div>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {[
          { label: `New Signups (${days}d)`, value: totalSignups, icon: Users, color: 'text-cyan-400' },
          { label: `Active Users (${days}d)`, value: totalActiveUsers, icon: TrendingUp, color: 'text-purple-400' },
          { label: `Revenue (${days}d)`, value: `₹${totalRevenue.toLocaleString('en-IN')}`, icon: CreditCard, color: 'text-emerald-400' },
        ].map(card => (
          <motion.div
            key={card.label}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="rounded-2xl p-5 border border-slate-700/50 bg-slate-900/40 backdrop-blur-xl"
          >
            <div className={`flex items-center gap-2 mb-2 ${card.color}`}>
              <card.icon className="w-4 h-4" />
              <span className="text-xs font-semibold uppercase tracking-wider text-slate-400">{card.label}</span>
            </div>
            <p className="text-3xl font-bold text-slate-100">{loading ? '...' : card.value}</p>
          </motion.div>
        ))}
      </div>

      {loading ? (
        <div className="flex items-center justify-center h-48">
          <div className="w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <div className="space-y-6">
          {/* User growth chart */}
          <SectionCard title="User Signups & Daily Active Users" icon={Users} color="text-cyan-400">
            {userChartData.length > 0 ? (
              <div className="h-[280px]">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={userChartData} margin={{ top: 10, right: 20, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="gSignups" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#06b6d4" stopOpacity={0.35} />
                        <stop offset="95%" stopColor="#06b6d4" stopOpacity={0} />
                      </linearGradient>
                      <linearGradient id="gActive" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#a78bfa" stopOpacity={0.35} />
                        <stop offset="95%" stopColor="#a78bfa" stopOpacity={0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} allowDecimals={false} />
                    <RechartsTooltip contentStyle={tooltipStyle} itemStyle={{ color: '#f8fafc' }} />
                    <Legend wrapperStyle={{ fontSize: '12px', color: '#cbd5e1' }} />
                    <Area type="monotone" dataKey="signups" name="New Signups" stroke="#06b6d4" strokeWidth={2} fillOpacity={1} fill="url(#gSignups)" />
                    <Area type="monotone" dataKey="active" name="Active Users" stroke="#a78bfa" strokeWidth={2} fillOpacity={1} fill="url(#gActive)" />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <p className="text-center text-slate-500 py-10">No user data for this period</p>
            )}
          </SectionCard>

          {/* Revenue chart */}
          <SectionCard title="Revenue" icon={CreditCard} color="text-emerald-400">
            {revenueChartData.length > 0 ? (
              <div className="h-[280px]">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={revenueChartData} margin={{ top: 10, right: 20, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} />
                    <XAxis dataKey="date" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} tickFormatter={v => `₹${v}`} />
                    <RechartsTooltip contentStyle={tooltipStyle} itemStyle={{ color: '#f8fafc' }} formatter={(v: unknown) => [`₹${v}`, 'Revenue']} />
                    <Bar dataKey="revenue" name="Revenue (₹)" fill="#10b981" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <p className="text-center text-slate-500 py-10">No revenue data for this period</p>
            )}
          </SectionCard>

          {/* Top channels */}
          <SectionCard title="Top 20 Channels by Plays (Last 30d)" icon={Tv} color="text-pink-400">
            {playbackData.length > 0 ? (
              <div className="h-[320px]">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={playbackData.slice(0, 20).map((r: unknown) => ({ name: r.name?.length > 18 ? r.name.slice(0, 18) + '…' : r.name, plays: parseInt(r.play_count) || 0 }))}
                    layout="vertical"
                    margin={{ top: 5, right: 30, left: 10, bottom: 5 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" horizontal={false} />
                    <XAxis type="number" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} />
                    <YAxis type="category" dataKey="name" stroke="#94a3b8" fontSize={11} tickLine={false} axisLine={false} width={120} />
                    <RechartsTooltip contentStyle={tooltipStyle} itemStyle={{ color: '#f8fafc' }} />
                    <Bar dataKey="plays" name="Plays" fill="#ec4899" radius={[0, 4, 4, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <p className="text-center text-slate-500 py-10">No playback data available. Watch history is recorded as users play channels.</p>
            )}
          </SectionCard>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { getAppSettings, updateAppSettings } from '@/lib/api';
import { motion } from 'framer-motion';
import { Settings, Save, Plus, Trash2, CheckCircle, X, AlertCircle, Info } from 'lucide-react';

const KNOWN_SETTINGS: Record<string, { label: string; desc: string; type: 'bool' | 'number' | 'text'; category: string }> = {
  maintenance_mode:      { label: 'Maintenance Mode',       desc: 'Show maintenance screen to all users',                                      type: 'bool',   category: 'App' },
  allow_unknown_streams: { label: 'Allow Unknown Streams',  desc: 'Show channels with unchecked stream health in the EPG',                     type: 'bool',   category: 'Channels' },
  force_update:          { label: 'Force App Update',       desc: 'Block old app versions from using the API',                                 type: 'bool',   category: 'Versioning' },
  minimum_app_version:   { label: 'Minimum App Version',    desc: 'e.g. 1.0.5 — older versions will be blocked from API access',               type: 'text',   category: 'Versioning' },
  latest_app_version:    { label: 'Latest App Version',     desc: 'Latest release version shown in app update notifications',                   type: 'text',   category: 'Versioning' },
  max_devices_per_user:  { label: 'Max Devices Per User',   desc: 'Default device limit (can be overridden by subscription plan)',             type: 'number', category: 'Users' },
  app_name:              { label: 'App Name',               desc: 'Displayed in notifications, splash screen, and email headers',               type: 'text',   category: 'Branding' },
  support_email:         { label: 'Support Email',          desc: 'Shown in app help section for user inquiries',                               type: 'text',   category: 'Support' },
  support_whatsapp:      { label: 'Support WhatsApp',       desc: 'WhatsApp number with country code for direct support',                      type: 'text',   category: 'Support' },
  default_language:      { label: 'Default Language',       desc: 'Fallback language when user has no preference (e.g., English, Hindi)',      type: 'text',   category: 'Localization' },
  epg_hours_ahead:       { label: 'EPG Hours Ahead',        desc: 'How many hours of guide data to fetch and display',                         type: 'number', category: 'Channels' },
  stream_check_interval: { label: 'Stream Check Interval',  desc: 'Minutes between automatic stream health checks (default: 60)',              type: 'number', category: 'Channels' },
};

function isBoolString(v: string) { return v === 'true' || v === 'false'; }

interface Toast { id: number; message: string; type: 'success'|'error'; }

export default function AppSettingsPage() {
  const [settings, setSettings] = useState<Record<string, string>>({});
  const [original, setOriginal] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [newKey, setNewKey] = useState('');
  const [newVal, setNewVal] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const toastId = useRef(0);

  const showToast = (message: string, type: 'success'|'error' = 'success') => {
    const id = ++toastId.current;
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3000);
  };

  const fetchSettings = () => {
    setLoading(true);
    getAppSettings()
      .then((d) => { setSettings(d || {}); setOriginal(d || {}); })
      .catch(() => showToast('Failed to load settings', 'error'))
      .finally(() => setLoading(false));
  };
  useEffect(() => { void Promise.resolve().then(fetchSettings); }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateAppSettings(settings as unknown as Record<string, unknown>);
      setOriginal({ ...settings });
      setSaved(true);
      setTimeout(() => setSaved(false), 2000);
      showToast('Settings saved successfully', 'success');
    } catch { showToast('Failed to save settings', 'error'); }
    finally { setSaving(false); }
  };

  const handleAddKey = () => {
    if (!newKey.trim()) { showToast('Please enter a key name', 'error'); return; }
    if (settings[newKey.trim()]) { showToast('Key already exists', 'error'); return; }
    setSettings((prev) => ({ ...prev, [newKey.trim()]: newVal }));
    setNewKey(''); setNewVal(''); setShowAdd(false);
    showToast('Setting added', 'success');
  };

  const handleDelete = (key: string) => {
    setSettings((prev) => { const n = { ...prev }; delete n[key]; return n; });
    showToast(`Setting "${key}" removed`, 'success');
  };

  const setVal = (key: string, val: string) => setSettings((prev) => ({ ...prev, [key]: val }));

  const isDirty = JSON.stringify(settings) !== JSON.stringify(original);

  const sortedKeys = Object.keys(settings).sort((a, b) => {
    const aMeta = KNOWN_SETTINGS[a]; const bMeta = KNOWN_SETTINGS[b];
    const aKnown = !!aMeta; const bKnown = !!bMeta;
    if (aKnown && !bKnown) return -1; if (!aKnown && bKnown) return 1;
    return a.localeCompare(b);
  });

  const grouped = sortedKeys.reduce((acc, key) => {
    const meta = KNOWN_SETTINGS[key];
    const category = meta?.category || 'Custom';
    if (!acc[category]) acc[category] = [];
    acc[category].push(key);
    return acc;
  }, {} as Record<string, string[]>);

  return (
    <div className="space-y-6 pb-10">
      {/* Toast Container */}
      <div className="fixed bottom-4 right-4 z-50 space-y-2">
        {toasts.map(t => (
          <motion.div key={t.id} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
            className={`flex items-center gap-2 px-4 py-3 rounded-xl shadow-lg border ${t.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-rose-500/10 border-rose-500/20 text-rose-400'}`}>
            {t.type === 'success' ? <CheckCircle className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
            <span className="text-sm font-medium">{t.message}</span>
          </motion.div>
        ))}
      </div>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-cyan-400">App Settings</h1>
          <p className="text-slate-400 mt-1">Configure global app behaviour, versioning and support information.</p>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowAdd(true)} className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800 border border-slate-700 text-slate-300 text-sm hover:bg-slate-700 transition-all">
            <Plus className="w-4 h-4" />Add Key
          </button>
          <button onClick={handleSave} disabled={saving || !isDirty} className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-cyan-500 text-white font-semibold hover:from-emerald-400 hover:to-cyan-400 shadow-lg shadow-emerald-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-all">
            {saved ? <CheckCircle className="w-4 h-4" /> : <Save className="w-4 h-4" />}
            {saved ? 'Saved!' : saving ? 'Saving…' : 'Save Changes'}
          </button>
        </div>
      </div>

      {showAdd && (
        <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} className="rounded-2xl border border-cyan-500/30 bg-cyan-500/5 p-4 flex items-end gap-3 flex-wrap">
          <div className="flex-1 min-w-48"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider block mb-1">Key</label>
            <input value={newKey} onChange={(e) => setNewKey(e.target.value)} placeholder="e.g., custom_setting" className="w-full px-3 py-2 rounded-xl bg-slate-900 border border-slate-700 text-slate-100 text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500/50" />
          </div>
          <div className="flex-1 min-w-48"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider block mb-1">Value</label>
            <input value={newVal} onChange={(e) => setNewVal(e.target.value)} placeholder="value" className="w-full px-3 py-2 rounded-xl bg-slate-900 border border-slate-700 text-slate-100 text-sm focus:outline-none focus:ring-2 focus:ring-cyan-500/50" />
          </div>
          <button onClick={handleAddKey} className="px-4 py-2 rounded-xl bg-cyan-500 text-white font-semibold text-sm hover:bg-cyan-400 transition-all">Add</button>
          <button onClick={() => setShowAdd(false)} className="p-2 rounded-xl bg-slate-800 text-slate-400 hover:text-slate-200 transition-all"><X className="w-4 h-4" /></button>
        </motion.div>
      )}

      {loading ? (
        <div className="flex justify-center h-48 items-center"><div className="w-10 h-10 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" /></div>
      ) : (
        <div className="space-y-6">
          {Object.entries(grouped).map(([category, keys]) => (
            <div key={category}>
              <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-3 flex items-center gap-2">
                {category === 'Custom' ? <Info className="w-4 h-4" /> : null}
                {category}
              </h2>
              <div className="space-y-2">
                {keys.map((key) => {
                  const meta = KNOWN_SETTINGS[key];
                  const val = settings[key] ?? '';
                  const isBool = meta?.type === 'bool' || (!meta && isBoolString(val));
                  const isNum = meta?.type === 'number';
                  return (
                    <motion.div key={key} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} className="rounded-xl border border-slate-700/50 bg-slate-900/40 backdrop-blur-xl p-4 flex items-center gap-4">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <Settings className="w-3.5 h-3.5 text-slate-500 shrink-0" />
                          <p className="font-semibold text-slate-200 text-sm">{meta?.label || key}</p>
                          {!meta && <span className="text-[10px] font-mono text-slate-500 bg-slate-800 px-1.5 py-0.5 rounded border border-slate-700">{key}</span>}
                        </div>
                        {meta?.desc && <p className="text-xs text-slate-500 mt-0.5 ml-5">{meta.desc}</p>}
                      </div>
                      <div className="shrink-0 w-64">
                        {isBool ? (
                          <div className="flex items-center gap-3">
                            <div onClick={() => setVal(key, val === 'true' ? 'false' : 'true')} className={`w-11 h-6 rounded-full cursor-pointer transition-colors relative ${val === 'true' ? 'bg-emerald-500' : 'bg-slate-700'}`}>
                              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-transform ${val === 'true' ? 'translate-x-6' : 'translate-x-1'}`} />
                            </div>
                            <span className={`text-sm font-semibold ${val === 'true' ? 'text-emerald-400' : 'text-slate-500'}`}>{val === 'true' ? 'Enabled' : 'Disabled'}</span>
                          </div>
                        ) : (
                          <input type={isNum ? 'number' : 'text'} value={val} onChange={(e) => setVal(key, e.target.value)}
                            className="w-full px-3 py-2 rounded-xl bg-slate-950/50 border border-slate-700 text-slate-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/50" />
                        )}
                      </div>
                      {!meta && (
                        <button onClick={() => handleDelete(key)} className="p-1.5 text-rose-400 hover:bg-rose-500/10 rounded-lg border border-transparent hover:border-rose-500/30 transition-all shrink-0" title="Delete setting">
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </motion.div>
                  );
                })}
              </div>
            </div>
          ))}
          {sortedKeys.length === 0 && (
            <div className="rounded-2xl border border-slate-700/50 bg-slate-900/40 p-12 text-center">
              <Settings className="w-10 h-10 mx-auto mb-3 text-slate-600" />
              <p className="text-slate-500">No settings configured yet.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { getCategories, createCategory, updateCategory, deleteCategory } from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Pencil, Check, X, FolderOpen, Trash2, AlertCircle } from 'lucide-react';

interface Category {
  id: string;
  name: string;
  icon_url: string;
  status: string;
  sort_order: number;
}

const emptyForm = { name: '', icon_url: '', status: 'active', sort_order: 0 };

export default function CategoriesPage() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);

  const fetchCategories = () => {
    setLoading(true);
    setError('');
    getCategories()
      .then((data) => setCategories(data || []))
      .catch((err) => setError(err?.message || 'Failed to load categories'))
      .finally(() => setLoading(false));
  }

  useEffect(() => { void Promise.resolve().then(fetchCategories); }, []);

  const openCreate = () => { setForm(emptyForm); setEditId(null); setShowModal(true); };

  const openEdit = (c: Category) => {
    setForm({ name: c.name, icon_url: c.icon_url || '', status: c.status, sort_order: c.sort_order || 0 });
    setEditId(c.id);
    setShowModal(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editId) {
        await updateCategory(editId, form);
      } else {
        await createCategory(form);
      }
      setShowModal(false);
      fetchCategories();
    } catch {
      alert('Failed to save category');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(`Delete category "${name}"? All channels in this category will become uncategorised.`)) return;
    try {
      await deleteCategory(id);
      fetchCategories();
    } catch {
      alert('Failed to delete category');
    }
  };

  return (
    <div className="space-y-6 pb-10">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-cyan-400">
            Categories
          </h1>
          <p className="text-slate-400 mt-1">Organise channels into browseable sections.</p>
        </div>
        <button
          onClick={openCreate}
          className="flex items-center gap-2 px-4 py-2 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-semibold hover:from-cyan-400 hover:to-blue-500 shadow-lg shadow-cyan-500/20 transition-all"
        >
          <Plus className="w-4 h-4" />
          New Category
        </button>
      </div>

      <AnimatePresence>
        {showModal && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center z-50 p-4"
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              className="bg-slate-900 border border-slate-700 p-6 rounded-2xl w-full max-w-md shadow-2xl relative overflow-hidden"
            >
              <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 to-cyan-500" />
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-slate-100 flex items-center gap-2">
                  <FolderOpen className="w-5 h-5 text-emerald-400" />
                  {editId ? 'Edit Category' : 'New Category'}
                </h3>
                <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-200">
                  <X className="w-5 h-5" />
                </button>
              </div>
              <form onSubmit={handleSubmit} className="space-y-4">
                {[
                  { label: 'Category Name', key: 'name', placeholder: 'e.g., Sports', required: true },
                  { label: 'Icon URL (optional)', key: 'icon_url', placeholder: 'https://...' },
                ].map(({ label, key, placeholder, required }) => (
                  <div key={key} className="space-y-1">
                    <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">{label}</label>
                    <input
                      value={(form as unknown)[key]}
                      onChange={(e) => setForm({ ...form, [key]: e.target.value })}
                      placeholder={placeholder}
                      required={required}
                      className="w-full px-4 py-2.5 rounded-xl bg-slate-950/50 border border-slate-700 text-slate-100 focus:outline-none focus:ring-2 focus:ring-cyan-500/50"
                    />
                  </div>
                ))}
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Status</label>
                    <select
                      value={form.status}
                      onChange={(e) => setForm({ ...form, status: e.target.value })}
                      className="w-full px-4 py-2.5 rounded-xl bg-slate-950/50 border border-slate-700 text-slate-100 focus:outline-none focus:ring-2 focus:ring-cyan-500/50"
                    >
                      <option value="active">Active</option>
                      <option value="inactive">Inactive</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Sort Order</label>
                    <input
                      type="number"
                      value={form.sort_order}
                      onChange={(e) => setForm({ ...form, sort_order: parseInt(e.target.value) || 0 })}
                      className="w-full px-4 py-2.5 rounded-xl bg-slate-950/50 border border-slate-700 text-slate-100 focus:outline-none focus:ring-2 focus:ring-cyan-500/50"
                    />
                  </div>
                </div>
                <div className="flex gap-3 pt-4">
                  <button
                    type="button"
                    onClick={() => setShowModal(false)}
                    className="flex-1 py-2.5 rounded-xl bg-slate-800 text-slate-200 font-semibold hover:bg-slate-700 border border-slate-700"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={saving}
                    className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-semibold hover:from-cyan-400 hover:to-blue-500 shadow-lg shadow-cyan-500/20 disabled:opacity-50"
                  >
                    {saving ? 'Saving…' : editId ? 'Update' : 'Create'}
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {error && (
        <div className="flex items-center gap-2 p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-400 text-sm">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{error}</span>
          <button onClick={fetchCategories} className="ml-auto px-3 py-1 rounded-lg bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs font-semibold hover:bg-rose-500/20 transition-all">Retry</button>
        </div>
      )}

      {loading ? (
        <div className="flex justify-center h-48 items-center">
          <div className="w-10 h-10 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <div className="bg-slate-900/40 backdrop-blur-xl border border-slate-700/50 rounded-2xl overflow-hidden shadow-2xl">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-slate-400 uppercase bg-slate-800/50 border-b border-slate-700/50">
                <tr>
                  <th className="px-6 py-4 font-semibold">Category</th>
                  <th className="px-6 py-4 font-semibold">Sort</th>
                  <th className="px-6 py-4 font-semibold">Status</th>
                  <th className="px-6 py-4 font-semibold text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-700/50">
                <AnimatePresence>
                  {categories.map((c) => (
                    <motion.tr
                      key={c.id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      className="hover:bg-slate-800/30 transition-colors group"
                    >
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-9 h-9 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center overflow-hidden">
                            {c.icon_url ? (
                              <img src={c.icon_url} alt={c.name} className="w-full h-full object-contain p-1" />
                            ) : (
                              <FolderOpen className="w-4 h-4 text-slate-500" />
                            )}
                          </div>
                          <span className="font-semibold text-slate-200 group-hover:text-cyan-400 transition-colors">{c.name}</span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-slate-400">{c.sort_order}</td>
                      <td className="px-6 py-4">
                        <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border ${
                          c.status === 'active'
                            ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                            : 'bg-slate-800 text-slate-400 border-slate-700'
                        }`}>
                          {c.status === 'active' ? <Check className="w-2.5 h-2.5" /> : <X className="w-2.5 h-2.5" />}
                          {c.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => openEdit(c)}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 text-cyan-400 hover:bg-cyan-500/10 hover:border-cyan-500/30 border border-slate-700 transition-all"
                          >
                            <Pencil className="w-3.5 h-3.5" />
                            Edit
                          </button>
                          <button
                            onClick={() => handleDelete(c.id, c.name)}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 text-rose-400 hover:bg-rose-500/10 hover:border-rose-500/30 border border-slate-700 transition-all"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                            Delete
                          </button>
                        </div>
                      </td>
                    </motion.tr>
                  ))}
                </AnimatePresence>
                {categories.length === 0 && (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                      <FolderOpen className="w-8 h-8 mx-auto mb-2 text-slate-600" />
                      No categories yet
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { getDuplicateChannels, mergeDuplicates, hideChannel } from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';
import { FileStack, RefreshCw, GitMerge, ChevronDown, ChevronUp, Tv, AlertTriangle, CheckCircle, AlertCircle } from 'lucide-react';

interface Channel { id: string; name: string; stream_url: string; health_status: string; quality: string; }
interface Group { canonical_name: string; count: number; channels: Channel[]; language?: string; category?: string; }

interface Toast { id: number; message: string; type: 'success' | 'error'; }

const HEALTH_CLS: Record<string, string> = {
  online:   'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  offline:  'bg-rose-500/10 text-rose-400 border-rose-500/20',
  unstable: 'bg-amber-500/10 text-amber-400 border-amber-500/20',
};

function ConfirmMergeModal({
  open, group, masterId, onConfirm, onCancel,
}: {
  open: boolean; group: Group | null; masterId: string; onConfirm: () => void; onCancel: () => void;
}) {
  if (!open || !group) return null;
  const master = group.channels.find(c => c.id === masterId);
  const dupes = group.channels.filter(c => c.id !== masterId);
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <motion.div initial={{ scale: 0.95, y: 16 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95 }}
        className="bg-slate-900 border border-slate-700 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden">
        <div className="h-1 w-full bg-gradient-to-r from-cyan-500 to-blue-600" />
        <div className="p-6">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 rounded-xl bg-amber-500/10 border border-amber-500/20">
              <AlertTriangle className="w-5 h-5 text-amber-400" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-100">Confirm Merge</h3>
              <p className="text-xs text-slate-500">{group.canonical_name}</p>
            </div>
          </div>

          <div className="space-y-3 mb-6">
            <div className="p-3 rounded-xl bg-cyan-500/5 border border-cyan-500/20">
              <p className="text-xs text-cyan-400 font-semibold uppercase tracking-wider mb-1">Keep as Master</p>
              <div className="flex items-center gap-2">
                <Tv className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                <p className="text-sm font-medium text-slate-200 truncate">{master?.name || '—'}</p>
                <span className={`ml-auto px-2 py-0.5 rounded-full text-[10px] font-bold border ${HEALTH_CLS[master?.health_status || ''] || 'bg-slate-800 text-slate-400 border-slate-700'}`}>{master?.health_status || 'unknown'}</span>
              </div>
            </div>

            <div className="p-3 rounded-xl bg-rose-500/5 border border-rose-500/20">
              <p className="text-xs text-rose-400 font-semibold uppercase tracking-wider mb-2">Will be merged & removed ({dupes.length})</p>
              <div className="space-y-1.5">
                {dupes.map(d => (
                  <div key={d.id} className="flex items-center gap-2">
                    <Tv className="w-3.5 h-3.5 text-slate-500 shrink-0" />
                    <p className="text-xs text-slate-400 truncate">{d.name}</p>
                  </div>
                ))}
              </div>
            </div>

            <p className="text-xs text-slate-500 text-center">Duplicate channels will be marked merged and their streams migrated to the master.</p>
          </div>

          <div className="flex gap-3">
            <button onClick={onCancel} className="flex-1 py-2.5 rounded-xl bg-slate-800 text-slate-200 font-semibold hover:bg-slate-700 border border-slate-700">Cancel</button>
            <button onClick={onConfirm} className="flex-1 py-2.5 rounded-xl font-semibold bg-gradient-to-r from-cyan-500 to-blue-600 text-white hover:from-cyan-400 hover:to-blue-500">
              Merge {dupes.length} Channel{dupes.length !== 1 ? 's' : ''}
            </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
}

export default function DuplicateChannelsPage() {
  const [groups, setGroups] = useState<Group[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [masterIds, setMasterIds] = useState<Record<string, string>>({});
  const [merging, setMerging] = useState<string | null>(null);
  const [hiding, setHiding] = useState<string | null>(null);
  const [confirmGroup, setConfirmGroup] = useState<Group | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const toastId = useRef(0);

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    const id = ++toastId.current;
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
  };

  const fetchDuplicates = () => {
    setLoading(true);
    getDuplicateChannels()
      .then((data: unknown) => {
        const g: Group[] = data?.groups || data || [];
        setGroups(g);
        setTotal(data?.total_groups ?? g.length);
        const defaults: Record<string, string> = {};
        g.forEach((gr) => { if (gr.channels?.[0]) defaults[gr.canonical_name] = gr.channels[0].id; });
        setMasterIds(defaults);
      })
      .catch(() => showToast('Failed to load duplicates', 'error'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { void Promise.resolve().then(fetchDuplicates); }, []);

  const requestMerge = (g: Group) => {
    const masterId = masterIds[g.canonical_name];
    const dupes = g.channels.filter(c => c.id !== masterId);
    if (!dupes.length) { showToast('All channels are set as master — change the master selection first', 'error'); return; }
    setConfirmGroup(g);
  };

  const executeMerge = async () => {
    if (!confirmGroup) return;
    const g = confirmGroup;
    setConfirmGroup(null);
    const masterId = masterIds[g.canonical_name] || g.channels[0]?.id;
    const dupIds = g.channels.filter(c => c.id !== masterId).map(c => c.id);
    setMerging(g.canonical_name);
    try {
      await mergeDuplicates({ masterId, duplicateIds: dupIds });
      setGroups(prev => prev.filter(gr => gr.canonical_name !== g.canonical_name));
      setTotal(prev => prev - 1);
      showToast(`"${g.canonical_name}" merged successfully`, 'success');
    } catch (err: unknown) {
      showToast(err?.response?.data?.message || 'Merge failed', 'error');
    } finally { setMerging(null); }
  };

  const executeHideSingle = async (e: React.MouseEvent, g: Group, channelId: string) => {
    e.stopPropagation();
    if (!confirm('Hide this individual channel?')) return;

    try {
      await hideChannel(channelId, 'Hidden from duplicates page', true);

      setGroups(prev => prev.map(gr => {
        if (gr.canonical_name === g.canonical_name) {
          const newChannels = gr.channels.filter(c => c.id !== channelId);
          return { ...gr, channels: newChannels, count: newChannels.length };
        }
        return gr;
      }).filter(gr => gr.channels.length > 1));

      showToast('Channel hidden successfully', 'success');
    } catch (err: unknown) {
      showToast('Failed to hide channel', 'error');
    }
  };

  const executeHideGroup = async (e: React.MouseEvent, g: Group) => {
    e.stopPropagation();
    if (!confirm('Are you sure you want to completely hide this entire group of channels from the app?')) return;

    setHiding(g.canonical_name);
    try {
      await Promise.all(g.channels.map(c => hideChannel(c.id, 'Duplicate group completely broken/unusable', true)));
      setGroups(prev => prev.filter(gr => gr.canonical_name !== g.canonical_name));
      setTotal(prev => prev - 1);
      showToast(`Entire group "${g.canonical_name}" hidden successfully`, 'success');
    } catch (err: unknown) {
      showToast(err?.response?.data?.message || 'Failed to hide group', 'error');
    } finally { 
      setHiding(null); 
    }
  };

  const toggleExpand = (name: string) =>
    setExpanded(prev => ({ ...prev, [name]: !prev[name] }));

  return (
    <div className="space-y-6 pb-10">
      {/* Toast Container */}
      <div className="fixed bottom-4 right-4 z-50 space-y-2 pointer-events-none">
        <AnimatePresence>
          {toasts.map(t => (
            <motion.div key={t.id} initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}
              className={`flex items-center gap-2 px-4 py-3 rounded-xl shadow-lg border ${t.type === 'success' ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400' : 'bg-rose-500/10 border-rose-500/20 text-rose-400'}`}>
              {t.type === 'success' ? <CheckCircle className="w-4 h-4 shrink-0" /> : <AlertCircle className="w-4 h-4 shrink-0" />}
              <span className="text-sm font-medium">{t.message}</span>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      <AnimatePresence>
        {confirmGroup && (
          <ConfirmMergeModal
            open={!!confirmGroup}
            group={confirmGroup}
            masterId={masterIds[confirmGroup.canonical_name] || confirmGroup.channels[0]?.id}
            onConfirm={executeMerge}
            onCancel={() => setConfirmGroup(null)}
          />
        )}
      </AnimatePresence>

      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-emerald-400 to-cyan-400">Duplicate Channels</h1>
          <p className="text-slate-400 mt-1">{total} duplicate group{total !== 1 ? 's' : ''} found</p>
        </div>
        <button onClick={fetchDuplicates} disabled={loading}
          className="flex items-center gap-2 px-3 py-2 rounded-xl bg-slate-800 border border-slate-700 text-slate-400 hover:text-slate-200 disabled:opacity-50 transition-all self-start">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
          <span className="text-sm">Refresh</span>
        </button>
      </div>

      {loading ? (
        <div className="flex justify-center h-48 items-center">
          <div className="w-10 h-10 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <div className="space-y-3">
          <AnimatePresence>
            {groups.map((g) => {
              const isOpen = expanded[g.canonical_name];
              const masterId = masterIds[g.canonical_name];
              const isMerging = merging === g.canonical_name;

              return (
                <motion.div key={g.canonical_name} layout
                  initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, height: 0 }}
                  className="rounded-2xl border border-slate-700/50 bg-slate-900/40 backdrop-blur-xl overflow-hidden">

                  {/* Group Header */}
                  <div className="flex items-center justify-between p-5 cursor-pointer select-none"
                    onClick={() => toggleExpand(g.canonical_name)}>
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="p-2 rounded-xl bg-cyan-500/10 border border-cyan-500/20 shrink-0">
                        <FileStack className="w-4 h-4 text-cyan-400" />
                      </div>
                      <div className="min-w-0">
                        <p className="font-semibold text-slate-200 truncate">{g.canonical_name}</p>
                        <div className="flex items-center gap-2 mt-0.5 flex-wrap">
                          <span className="text-xs text-rose-400">{g.count} duplicate{g.count !== 1 ? 's' : ''}</span>
                          {g.language && <span className="text-xs text-slate-500">· {g.language}</span>}
                          {g.category && <span className="text-xs text-slate-500">· {g.category}</span>}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 shrink-0 ml-3">
                      <button onClick={(e) => { e.stopPropagation(); requestMerge(g); }} disabled={isMerging || hiding === g.canonical_name}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold bg-gradient-to-r from-cyan-500 to-blue-600 text-white hover:from-cyan-400 hover:to-blue-500 disabled:opacity-50 transition-all shadow-sm">
                        <GitMerge className={`w-3.5 h-3.5 ${isMerging ? 'animate-spin' : ''}`} />
                        {isMerging ? 'Merging…' : 'Merge'}
                      </button>
                      <button onClick={(e) => executeHideGroup(e, g)} disabled={hiding === g.canonical_name || isMerging}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-semibold bg-slate-800 border border-slate-700 text-rose-400 hover:bg-rose-500/10 hover:border-rose-500/20 hover:text-rose-300 disabled:opacity-50 transition-all shadow-sm">
                        <AlertTriangle className={`w-3.5 h-3.5 ${hiding === g.canonical_name ? 'animate-pulse' : ''}`} />
                        {hiding === g.canonical_name ? 'Hiding…' : 'Hide All'}
                      </button>
                      {isOpen ? <ChevronUp className="w-4 h-4 text-slate-500" /> : <ChevronDown className="w-4 h-4 text-slate-500" />}
                    </div>
                  </div>

                  {/* Expanded Channel List */}
                  <AnimatePresence>
                    {isOpen && (
                      <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }}
                        className="overflow-hidden border-t border-slate-700/50">
                        <div className="p-4 space-y-2">
                          <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3">
                            Select master — duplicates will be merged into it
                          </p>
                          {g.channels?.map((c) => (
                            <label key={c.id} onClick={(e) => e.stopPropagation()}
                              className={`flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all ${
                                masterId === c.id
                                  ? 'bg-cyan-500/10 border border-cyan-500/30'
                                  : 'bg-slate-800/40 border border-slate-700/50 hover:bg-slate-800/70'
                              }`}>
                              <input type="radio" name={`master-${g.canonical_name}`} value={c.id}
                                checked={masterId === c.id}
                                onChange={() => setMasterIds(prev => ({ ...prev, [g.canonical_name]: c.id }))}
                                className="accent-cyan-500 shrink-0" />
                              <Tv className="w-4 h-4 text-slate-500 shrink-0" />
                              <div className="min-w-0 flex-1">
                                <p className="text-sm font-medium text-slate-200 truncate">{c.name}</p>
                                <p className="text-xs text-slate-500 font-mono truncate">{c.stream_url || 'No stream URL'}</p>
                              </div>
                              <div className="flex items-center gap-2 shrink-0">
                                {c.quality && <span className="text-[10px] font-bold text-slate-500 bg-slate-800 px-1.5 py-0.5 rounded border border-slate-700">{c.quality}</span>}
                                <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${HEALTH_CLS[c.health_status] || 'bg-slate-800 text-slate-400 border-slate-700'}`}>
                                  {c.health_status || 'unknown'}
                                </span>
                                <button onClick={(e) => executeHideSingle(e, g, c.id)}
                                  className="px-2 py-1 rounded bg-slate-800 border border-slate-700 text-rose-400 hover:bg-rose-500/20 hover:text-rose-300 text-[10px] font-bold uppercase transition-all">
                                  Hide
                                </button>
                                {masterId === c.id ? (
                                  <span className="text-[10px] font-bold text-cyan-400 bg-cyan-500/10 px-2 py-0.5 rounded border border-cyan-500/20">MASTER</span>
                                ) : (
                                  <span className="text-[10px] font-bold text-slate-500 bg-slate-800 px-2 py-0.5 rounded border border-slate-700">SUB</span>
                                )}
                              </div>
                            </label>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </motion.div>
              );
            })}
          </AnimatePresence>

          {groups.length === 0 && (
            <div className="rounded-2xl border border-slate-700/50 bg-slate-900/40 p-12 text-center">
              <FileStack className="w-12 h-12 mx-auto mb-3 text-slate-600" />
              <p className="text-lg font-semibold text-slate-400 mb-1">Library is clean</p>
              <p className="text-slate-500 text-sm">No duplicate channels found.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { getHiddenChannels, restoreChannel } from '@/lib/api';
import { EyeOff, RefreshCw, Undo2 } from 'lucide-react';
import { motion } from 'framer-motion';

export default function HiddenChannelsPage() {
  const [channels, setChannels] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchHidden = async () => {
    setLoading(true);
    try {
      const data = await getHiddenChannels();
      setChannels(data || []);
    } catch (err) {
      console.error(err);
    }
    setLoading(false);
  };

  useEffect(() => {
    void Promise.resolve().then(fetchHidden);
  }, []);

  const handleRestore = async (id: string) => {
    if (!confirm('Are you sure you want to restore this channel? It will be visible in the app again.')) return;
    try {
      await restoreChannel(id, true);
      setChannels(channels.filter(c => c.id !== id));
    } catch (err) {
      alert('Failed to restore channel');
    }
  };

  return (
    <div className="p-6 max-w-6xl mx-auto space-y-6">
      <div className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="p-3 bg-amber-500/10 rounded-xl border border-amber-500/20">
            <EyeOff className="w-6 h-6 text-amber-400" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white">Hidden Channels</h1>
            <p className="text-sm text-slate-400">Channels that are temporarily hidden from the public API</p>
          </div>
        </div>
        <button onClick={fetchHidden} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-sm text-slate-200">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Refresh
        </button>
      </div>

      <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-950/50 text-slate-400 text-xs uppercase tracking-wider">
                <th className="px-4 py-3 font-medium">Channel</th>
                <th className="px-4 py-3 font-medium">Category / Lang</th>
                <th className="px-4 py-3 font-medium">Hidden Reason</th>
                <th className="px-4 py-3 font-medium">Hidden At</th>
                <th className="px-4 py-3 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {channels.length === 0 ? (
                <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-500 text-sm">No hidden channels found</td></tr>
              ) : channels.map((c) => (
                <motion.tr initial={{ opacity: 0 }} animate={{ opacity: 1 }} key={c.id} className="text-sm text-slate-300 hover:bg-slate-800/30">
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      {c.logo_url ? <img src={c.logo_url} alt="" className="w-8 h-8 rounded bg-slate-800 object-contain" /> : <div className="w-8 h-8 rounded bg-slate-800" />}
                      <span className="font-semibold text-slate-200">{c.name}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-xs">
                    <div className="text-slate-300">{c.category_name}</div>
                    <div className="text-slate-500">{c.language}</div>
                  </td>
                  <td className="px-4 py-3 text-xs text-amber-400/80 italic max-w-xs truncate">
                    {c.hidden_reason || 'No reason provided'}
                  </td>
                  <td className="px-4 py-3 text-xs text-slate-500">
                    {c.hidden_at ? new Date(c.hidden_at).toLocaleString() : '-'}
                  </td>
                  <td className="px-4 py-3">
                    <button onClick={() => handleRestore(c.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 rounded-lg text-xs font-semibold transition-colors">
                      <Undo2 className="w-3.5 h-3.5" /> Restore
                    </button>
                  </td>
                </motion.tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { getChannels, getCategories, createChannel, updateChannel, deleteChannel, getChannelStreams, createChannelStream, updateChannelStream, deleteChannelStream, diagnoseChannelStream } from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Plus, Trash2, Tv, Globe2, Languages, Signal, X, Pencil, List, ChevronLeft, ChevronRight, Link2, Check, XCircle, Play, Edit3, RefreshCw } from 'lucide-react';
import ChannelLogoImage from '@/components/ChannelLogoImage';

interface Channel {
  id: string; name: string; logo_url: string; stream_url: string;
  category_id: string; category_name: string; language: string; quality: string;
  status: string; health_status: string; is_premium: boolean; is_featured: boolean;
  sort_order: number; backup_stream_url: string;
}
interface Stream { 
  id: string; 
  stream_url: string; 
  quality: string; 
  priority: number; 
  health_status: string; 
  source_name: string; 
  is_active?: boolean;
  user_agent?: string;
  referer?: string;
  origin?: string;
  headers_json?: unknown;
  playback_mode?: string;
  codec_video?: string;
  codec_audio?: string;
  container_type?: string;
  segment_type?: string;
  health_reason?: string;
  android_playable?: boolean;
  vlc_playable?: boolean;
}

const emptyForm = { name: '', stream_url: '', backup_stream_url: '', logo_url: '', category_id: '', language: 'Hindi', quality: 'HD', status: 'active', is_premium: false, is_featured: false, sort_order: 0 };

function HealthBadge({ status }: { status: string }) {
  const c: Record<string, string> = { online: 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400', offline: 'bg-rose-500/10 border-rose-500/20 text-rose-400', unstable: 'bg-amber-500/10 border-amber-500/20 text-amber-400' };
  return <span className={`inline-flex px-2.5 py-1 rounded-full text-[10px] font-bold uppercase border ${c[status] || 'bg-slate-800 border-slate-700 text-slate-400'}`}>{status || 'unknown'}</span>;
}

function StreamHealthIndicator({ status }: { status: string }) {
  if (status === 'online') return <span className="flex items-center gap-1 text-emerald-400"><span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />Live</span>;
  if (status === 'offline') return <span className="flex items-center gap-1 text-rose-400"><XCircle className="w-3 h-3" />Down</span>;
  if (status === 'unstable') return <span className="flex items-center gap-1 text-amber-400"><span className="w-2 h-2 rounded-full bg-amber-400" />Unstable</span>;
  return <span className="text-slate-500">—</span>;
}

export default function ChannelsPage() {
  const [channels, setChannels] = useState<Channel[]>([]);
  const [categories, setCategories] = useState<unknown[]>([]);
  const [total, setTotal] = useState(0);
  const [activeTotal, setActiveTotal] = useState(0);
  const [page, setPage] = useState(1); const PAGE = 50;
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState(''); const [catFilter, setCatFilter] = useState('');
  const [modal, setModal] = useState<'create' | 'edit' | 'streams' | null>(null);
  const [editChannel, setEditChannel] = useState<Channel | null>(null);
  const [form, setForm] = useState(emptyForm);
  const [streams, setStreams] = useState<Stream[]>([]);
  const [streamChannelId, setStreamChannelId] = useState<string | null>(null);

  const emptyStreamForm = {
    stream_url: '',
    quality: 'HD',
    priority: 1,
    source_name: '',
    is_active: true,
    user_agent: '',
    referer: '',
    origin: '',
    headers_json: '',
    playback_mode: 'direct'
  };

  const [streamForm, setStreamForm] = useState(emptyStreamForm);
  const [editingStreamId, setEditingStreamId] = useState<string | null>(null);
  const [diagnosingId, setDiagnosingId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [selectedStreams, setSelectedStreams] = useState<Set<string>>(new Set());

  const fetchChannels = (p = page, s = search, cat = catFilter) => {
    setLoading(true);
    const params: Record<string, unknown> = { page: p, limit: PAGE };
    if (s) params.search = s;
    if (cat) params.category_id = cat;
    getChannels(params)
      .then((res: unknown) => {
        if (res?.data) { 
          setChannels(res.data); 
          setTotal(res.pagination?.total || 0); 
          setActiveTotal(res.pagination?.active || 0);
        }
        else { setChannels(Array.isArray(res) ? res : []); }
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => { getCategories().then((d) => setCategories(d || [])); }, []);
  useEffect(() => { void Promise.resolve().then(() => { fetchChannels(1, search, catFilter); setPage(1); }); }, [search, catFilter]);

  const openCreate = () => { setForm(emptyForm); setModal('create'); };
  const openEdit = (c: Channel) => {
    setEditChannel(c);
    setForm({ name: c.name, stream_url: c.stream_url || '', backup_stream_url: c.backup_stream_url || '', logo_url: c.logo_url || '', category_id: c.category_id || '', language: c.language || 'Hindi', quality: c.quality || 'HD', status: c.status, is_premium: c.is_premium, is_featured: c.is_featured, sort_order: c.sort_order || 0 });
    setModal('edit');
  };
  const openStreams = async (c: Channel) => {
    setStreamChannelId(c.id); 
    setStreamForm(emptyStreamForm);
    setEditingStreamId(null);
    setSelectedStreams(new Set());
    try { const d = await getChannelStreams(c.id); setStreams(d || []); } catch { setStreams([]); }
    setModal('streams');
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault(); setSaving(true);
    try { await createChannel(form as unknown as Record<string, unknown>); setModal(null); fetchChannels(); }
    catch (err: unknown) { alert(err?.response?.data?.message || 'Failed to create channel'); }
    finally { setSaving(false); }
  };

  const handleEdit = async (e: React.FormEvent) => {
    e.preventDefault(); if (!editChannel) return; setSaving(true);
    try { await updateChannel(editChannel.id, form as unknown as Record<string, unknown>); setModal(null); fetchChannels(); }
    catch (err: unknown) { alert(err?.response?.data?.message || 'Failed to update channel'); }
    finally { setSaving(false); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this channel? This cannot be undone.')) return;
    try { await deleteChannel(id); fetchChannels(); }
    catch { alert('Failed to delete channel'); }
  };

  const handleAddStream = async (e: React.FormEvent) => {
    e.preventDefault(); if (!streamChannelId) return; setSaving(true);
    try { 
      const d = await createChannelStream({ ...streamForm, channel_id: streamChannelId }); 
      setStreams((p) => [...p, d]); 
      setStreamForm(emptyStreamForm); 
    }
    catch { alert('Failed to add stream'); }
    finally { setSaving(false); }
  };

  const handleUpdateStream = async (e: React.FormEvent) => {
    e.preventDefault(); if (!editingStreamId) return; setSaving(true);
    try {
      const d = await updateChannelStream(editingStreamId, streamForm);
      setStreams((p) => p.map((s) => (s.id === editingStreamId ? { ...s, ...d } : s)));
      setEditingStreamId(null);
      setStreamForm(emptyStreamForm);
    } catch { alert('Failed to update stream'); }
    finally { setSaving(false); }
  };

  const handleDiagnoseStream = async (sid: string) => {
    setDiagnosingId(sid);
    try {
      const result = await diagnoseChannelStream(sid);
      if (streamChannelId) {
        const d = await getChannelStreams(streamChannelId);
        setStreams(d || []);
      }
    } catch (err: unknown) {
      alert(err?.response?.data?.message || err?.message || 'Failed to run diagnosis');
    } finally {
      setDiagnosingId(null);
    }
  };

  const handleDeleteStream = async (sid: string) => {
    if (!confirm('Delete this stream?')) return;
    try { await deleteChannelStream(sid); setStreams((p) => p.filter((s) => s.id !== sid)); setSelectedStreams((s) => { const n = new Set(s); n.delete(sid); return n; }); }
    catch { alert('Failed to delete stream'); }
  };

  const startEditStream = (s: Stream) => {
    setEditingStreamId(s.id);
    setStreamForm({ 
      stream_url: s.stream_url, 
      quality: s.quality || 'HD', 
      priority: s.priority || 1, 
      source_name: s.source_name || '',
      is_active: s.is_active !== false,
      user_agent: s.user_agent || '',
      referer: s.referer || '',
      origin: s.origin || '',
      headers_json: s.headers_json ? (typeof s.headers_json === 'string' ? s.headers_json : JSON.stringify(s.headers_json, null, 2)) : '',
      playback_mode: s.playback_mode || 'direct'
    });
  };

  const cancelEditStream = () => {
    setEditingStreamId(null);
    setStreamForm(emptyStreamForm);
  };

  const toggleStreamSelection = (id: string) => {
    setSelectedStreams((s) => {
      const n = new Set(s);
      if (n.has(id)) n.delete(id);
      else n.add(id);
      return n;
    });
  };

  const selectAllStreams = () => {
    if (selectedStreams.size === streams.length) {
      setSelectedStreams(new Set());
    } else {
      setSelectedStreams(new Set(streams.map(s => s.id)));
    }
  };

  const bulkDeleteStreams = async () => {
    if (selectedStreams.size === 0) return;
    if (!confirm(`Delete ${selectedStreams.size} selected streams?`)) return;
    setSaving(true);
    try {
      await Promise.all(Array.from(selectedStreams).map(id => deleteChannelStream(id)));
      setStreams((p) => p.filter((s) => !selectedStreams.has(s.id)));
      setSelectedStreams(new Set());
    } catch { alert('Failed to delete some streams'); }
    finally { setSaving(false); }
  };

  const pages = Math.max(1, Math.ceil(total / PAGE));
  const goPage = (p: number) => { setPage(p); fetchChannels(p, search, catFilter); };
  const ic = 'w-full px-4 py-2.5 rounded-xl bg-slate-950/50 border border-slate-700 text-slate-100 focus:outline-none focus:ring-2 focus:ring-cyan-500/50';

  const renderChannelModal = (mode: 'create' | 'edit') => (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <motion.div initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95, y: 20 }} className="bg-slate-900 border border-slate-700 p-6 rounded-2xl w-full max-w-2xl shadow-2xl relative overflow-hidden max-h-[90vh] overflow-y-auto">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-cyan-500 to-blue-500" />
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold text-slate-100 flex items-center gap-2"><Tv className="w-5 h-5 text-cyan-400" />{mode === 'create' ? 'Add New Channel' : 'Edit Channel'}</h3>
          <button onClick={() => setModal(null)} className="text-slate-400 hover:text-slate-200"><X className="w-5 h-5" /></button>
        </div>
        <form onSubmit={mode === 'create' ? handleCreate : handleEdit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2 space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Channel Name *</label><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g., Star Sports 1" className={ic} required /></div>
            <div className="col-span-2 space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Stream URL *</label><input value={form.stream_url} onChange={(e) => setForm({ ...form, stream_url: e.target.value })} placeholder="http://..." className={ic} required /></div>
            <div className="col-span-2 space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Backup Stream URL</label><input value={form.backup_stream_url} onChange={(e) => setForm({ ...form, backup_stream_url: e.target.value })} placeholder="http://..." className={ic} /></div>
            <div className="col-span-2 space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Logo URL</label><input value={form.logo_url} onChange={(e) => setForm({ ...form, logo_url: e.target.value })} placeholder="https://..." className={ic} /></div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Category</label>
              <select value={form.category_id} onChange={(e) => setForm({ ...form, category_id: e.target.value })} className={ic}>
                <option value="">— None —</option>
                {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div className="space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Language</label><input value={form.language} onChange={(e) => setForm({ ...form, language: e.target.value })} placeholder="Hindi" className={ic} /></div>
            <div className="space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Quality</label>
              <select value={form.quality} onChange={(e) => setForm({ ...form, quality: e.target.value })} className={ic}>
                {['SD','HD','FHD','4K'].map(q => <option key={q} value={q}>{q}</option>)}
              </select>
            </div>
            <div className="space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Status</label>
              <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className={ic}>
                <option value="active">Active</option><option value="inactive">Inactive</option>
              </select>
            </div>
            <div className="space-y-1"><label className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Sort Order</label><input type="number" value={form.sort_order} onChange={(e) => setForm({ ...form, sort_order: parseInt(e.target.value) || 0 })} className={ic} /></div>
          </div>
          <div className="flex gap-6">
            {([['is_premium','Premium Channel'],['is_featured','Featured']] as const).map(([k,l]) => (
              <label key={k} className="flex items-center gap-2 cursor-pointer">
                <div onClick={() => setForm({ ...form, [k]: !(form as unknown)[k] })} className={`w-9 h-5 rounded-full transition-colors relative ${(form as unknown)[k] ? 'bg-emerald-500' : 'bg-slate-700'}`}>
                  <div className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${(form as unknown)[k] ? 'translate-x-4' : 'translate-x-0.5'}`} />
                </div>
                <span className="text-sm text-slate-300">{l}</span>
              </label>
            ))}
          </div>
          <div className="flex gap-3 pt-4">
            <button type="button" onClick={() => setModal(null)} className="flex-1 py-2.5 rounded-xl bg-slate-800 text-slate-200 font-semibold hover:bg-slate-700 border border-slate-700">Cancel</button>
            <button type="submit" disabled={saving} className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-semibold disabled:opacity-50">{saving ? 'Saving…' : mode === 'create' ? 'Create Channel' : 'Save Changes'}</button>
          </div>
        </form>
      </motion.div>
    </motion.div>
  );

  const renderStreamsModal = () => (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <motion.div initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95, y: 20 }} className="bg-slate-900 border border-slate-700 p-6 rounded-2xl w-full max-w-4xl shadow-2xl relative overflow-hidden max-h-[90vh] overflow-y-auto">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-purple-500 to-pink-500" />
        <div className="flex justify-between items-center mb-5">
          <h3 className="text-xl font-bold text-slate-100 flex items-center gap-2"><Link2 className="w-5 h-5 text-purple-400" />Stream Sources</h3>
          <div className="flex items-center gap-2">
            {selectedStreams.size > 0 && (
              <button onClick={bulkDeleteStreams} disabled={saving} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-rose-500/10 text-rose-400 border border-rose-500/30 hover:bg-rose-500/20 transition-all">
                <Trash2 className="w-3.5 h-3.5" /> Delete ({selectedStreams.size})
              </button>
            )}
            <button onClick={() => setModal(null)} className="text-slate-400 hover:text-slate-200"><X className="w-5 h-5" /></button>
          </div>
        </div>

        {/* Stream List */}
        <div className="space-y-3 mb-5 max-h-[45vh] overflow-y-auto pr-1">
          {streams.length > 0 && (
            <div className="flex items-center gap-2 px-3 py-2 text-xs text-slate-400 border-b border-slate-700/50">
              <input 
                type="checkbox" 
                checked={selectedStreams.size === streams.length} 
                onChange={selectAllStreams}
                className="w-4 h-4 rounded bg-slate-800 border-slate-600 text-purple-500 focus:ring-purple-500/50"
              />
              <span>Select all</span>
            </div>
          )}
          {streams.map((s) => (
